class CompositeGenericKeyMatch(Expression):
    """
    Join/whole predicate matching a GenericForeignKey's JSON-array text
    reference (``object_id``) against the individual columns of a related
    model's CompositePrimaryKey.

    The predicate is defensive about the stored reference:

    * a SQL NULL reference never matches;
    * malformed JSON, a non-array value, or an array with the wrong number of
      components never match and never raise a database error (the element
      checks are only evaluated inside a ``CASE`` once the reference has been
      validated);
    * each element must have exactly the JSON type produced by the component
      field, so an integer can't stand in for a string, the booleans
      ``true``/``false`` can't stand in for 1/0, and a JSON ``null`` only
      matches a column that is itself NULL.

    ``object_id_col`` is the column (on the source table) holding the JSON
    reference; ``target_cols`` are the composite primary key columns (on the
    target table). When the predicate is used to correlate a ``split_exclude()``
    subquery with its outer query, ``target_cols`` isn't known up front and an
    ``outer_pk`` expression (resolving to the outer composite primary key) is
    given instead; it's resolved against the outer query by
    resolve_expression().
    """

    conditional = True
    output_field = models.BooleanField()

    def __init__(self, object_id_col, target_cols=(), outer_pk=None):
        super().__init__()
        self.object_id_col = object_id_col
        self.target_cols = tuple(target_cols)
        self.outer_pk = outer_pk

    @classmethod
    def for_aliases(cls, source_alias, object_id_field, target_alias, pk_fields):
        return cls(
            Col(source_alias, object_id_field),
            target_cols=[Col(target_alias, field) for field in pk_fields],
        )

    @classmethod
    def correlated(cls, object_id_col, outer_pk):
        return cls(object_id_col, outer_pk=outer_pk)

    def __repr__(self):
        return "<%s: %s -> %s composite primary key>" % (
            self.__class__.__name__,
            self.object_id_col,
            self.outer_pk if self.outer_pk is not None else self.target_cols,
        )

    def get_source_expressions(self):
        if self.outer_pk is not None:
            return [self.object_id_col, self.outer_pk]
        return [self.object_id_col, *self.target_cols]

    def set_source_expressions(self, exprs):
        self.object_id_col = exprs[0]
        if self.outer_pk is not None:
            resolved_pk = exprs[1]
            self.outer_pk = None
            # The outer composite primary key resolves to a ColPairs (or, after
            # a relabel, an iterable of Cols); use its individual columns.
            self.target_cols = tuple(
                col if isinstance(col, Col) else Col(col.alias, col.target)
                for col in resolved_pk
            )
        else:
            self.target_cols = tuple(exprs[1:])

    def relabeled_clone(self, relabels):
        return self.__class__(
            self.object_id_col.relabeled_clone(relabels),
            target_cols=[col.relabeled_clone(relabels) for col in self.target_cols],
            outer_pk=self.outer_pk,
        )

    def as_sqlite(self, compiler, connection):
        ref_sql, _ = compiler.compile(self.object_id_col)
        ref = ref_sql % ()
        fragments = [
            f"{ref} IS NOT NULL",
            f"json_valid({ref}) = 1",
            f"json_type({ref}) = 'array'",
            f"json_array_length({ref}) = %s",
        ]
        params = [len(self.target_cols)]
        for index, col in enumerate(self.target_cols):
            col_sql, col_params = compiler.compile(col)
            path = "$[%d]" % index
            json_type_name = _composite_component_json_type(col.target)
            null_type_sql = f"json_type({ref}, %s)"
            value_type_sql = (
                f"{null_type_sql} IN ('true', 'false')"
                if json_type_name == "boolean"
                else f"{null_type_sql} = %s"
            )
            fragments.append(
                "("
                f"({null_type_sql} = 'null' AND {col_sql} IS NULL) OR "
                f"({value_type_sql} AND json_extract({ref}, %s) = {col_sql})"
                ")"
            )
            if json_type_name == "boolean":
                # null check path; value check path; extract path
                params.extend([path, path, path])
            else:
                # null check path; value check path + JSON type name; extract
                params.extend([path, path, json_type_name, path])
            params.extend(col_params)
        return "CASE WHEN %s THEN 1 END" % " AND ".join(fragments), tuple(params)

    def as_sql(self, compiler, connection):
        raise NotSupportedError(
            "Cross-relation queries on a GenericRelation to a model with a "
            "CompositePrimaryKey are only supported on database backends that "
            "can query the stored JSON object reference."
        )


