from django.db.models import Count, Exists, OuterRef, Q
from django.test import TestCase

from .models import (
    GFKCompositeAttachment,
    GFKCompositeTarget,
)


class EdgeTestCase(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.a = GFKCompositeTarget.objects.create(code=1, tenant="1")
        cls.b = GFKCompositeTarget.objects.create(code=1, tenant="2")
        cls.c = GFKCompositeTarget.objects.create(code=3, tenant="3")
        cls.sa1 = GFKCompositeAttachment.objects.create(text="a1", n=10, content_object=cls.a)
        cls.sa2 = GFKCompositeAttachment.objects.create(text="a2", n=None, content_object=cls.a)
        cls.sb = GFKCompositeAttachment.objects.create(text="b", n=30, content_object=cls.b)

    def test_annotate_count(self):
        # Annotation over the reverse relation combined with cross filter.
        qs = GFKCompositeTarget.objects.filter(
            attachments__n__isnull=False
        ).annotate(num=Count("attachments__pk")).order_by("pk")
        rows = [(t.pk, t.num) for t in qs]
        # a has one non-null n source; b has one. Distinct keeps one row each.
        self.assertEqual(rows, [((1, "1"), 1), ((1, "2"), 1)])

    def test_exists_subquery(self):
        sub = GFKCompositeAttachment.objects.filter(
            content_object=OuterRef("pk"), text="a1"
        )
        hits = list(GFKCompositeTarget.objects.filter(Exists(sub)).order_by("pk"))
        self.assertEqual([t.pk for t in hits], [(1, "1")])

    def test_isnull_true(self):
        # targets having at least one source with n IS NULL
        hits = sorted(
            GFKCompositeTarget.objects.filter(
                attachments__n__isnull=True
            ).values_list("code", "tenant")
        )
        # LEFT JOIN: a qualifies (a2.n null); also targets with no sources
        # qualify under isnull semantics, like normal reverse relations.
        self.assertIn((1, "1"), hits)
        print("isnull true hits:", hits)

    def test_only_defer(self):
        objs = list(
            GFKCompositeTarget.objects.filter(
                attachments__text="a1"
            ).only("code", "tenant")
        )
        self.assertEqual([o.pk for o in objs], [(1, "1")])

    def test_values_pk(self):
        vals = set(
            GFKCompositeTarget.objects.filter(
                attachments__text__startswith="a"
            ).values_list("pk")
        )
        self.assertEqual(vals, {(1, "1")})

    def test_double_relation_conditions_or(self):
        qs = GFKCompositeTarget.objects.filter(
            Q(attachments__text="a1") | Q(attachments__n=30)
        )
        self.assertEqual(
            set(qs.values_list("code", "tenant")), {(1, "1"), (1, "2")}
        )

    def test_filter_in_queryset(self):
        src_qs = GFKCompositeAttachment.objects.filter(n__gte=20)
        qs = GFKCompositeTarget.objects.filter(attachments__in=src_qs)
        self.assertEqual(
            set(qs.values_list("code", "tenant")), {(1, "1"), (1, "2")}
        )

    def test_exists(self):
        self.assertTrue(
            GFKCompositeTarget.objects.filter(attachments__text="a1").exists()
        )
        self.assertFalse(
            GFKCompositeTarget.objects.filter(attachments__text="zzz").exists()
        )

    def test_first(self):
        obj = GFKCompositeTarget.objects.filter(attachments__n=30).first()
        self.assertEqual(obj, self.b)

