        )

    def test_exclude_comparison(self):
        self.assertEqual(
            self._targets(
                GFKCompositeTarget.objects.exclude(attachments__n__gte=15)
            ),
            # target_a (n=10/20) and target_b (n=30) both have a high source;
            # only target_c, with no source, survives.
